import React, { useState } from 'react'
import { COLORS, SIZES } from '../../Theme/Theme'
import { IMAGES } from '../../Theme/Image'
import { useNavigate, useLocation } from 'react-router-dom'
import Loading from '../../Component/Loading'
import useMediaQuery from '../../Component/useMediaQuery'
import InputForm from "../../Component/InputForm";
import DropDown from "../../Component/DropDown/DropDown";
import { checking } from "../../Component/Constants";
import { useDispatch, useSelector } from 'react-redux'
import Modal from 'react-modal';
import axiosIns from '../../helpers/helpers'
import TextButton from '../../Component/TextButton'
import { getMedical } from '../../Store/actions'
import { useAlert } from 'react-alert'
import moment from 'moment'

// Icons
const BackIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-[#009A48]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
  </svg>
);

const PlusIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-1" viewBox="0 0 20 20" fill="currentColor">
    <path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" />
  </svg>
);

const MedicalIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
  </svg>
);

export default function History() {
  const navigate = useNavigate()
  const { state } = useLocation();
  const { data } = state;
  // const med = useSelector(state => state.Reducers.med) // Unused in original rendering but kept for logic safety if needed
  const [medicine, setmedicine] = useState("");
  const [medicationR, setmedicationR] = useState("");
  const [dosage, setdosage] = useState("");
  const [vaccinateddate, setVaccinateddate] = useState("");
  const [withdrawal_date, setwithdrawal_date] = useState(null);
  const [loading, setLoading] = useState(null);
  const [withdrawal, setwithdrawal] = useState(null);
  const matches = useMediaQuery('(max-width:820px)')
  const mobile = useMediaQuery('(min-width:460px)')

  // Modal Logic
  let subtitle;
  const [modalIsOpen, setIsOpen] = React.useState(false);

  function openModal() {
    setIsOpen(true);
  }

  function afterOpenModal() {
    // references are now sync'd and can be accessed.
    subtitle.style.color = '#000000c4';
  }

  function closeModal() {
    setIsOpen(false);
  }

  const dispatch = useDispatch()
  const alert = useAlert()

  function addmedical() {
    setLoading(true)
    axiosIns.post('/medication/',
      {
        tag_number: data[0].tag_number,
        medication_name: medicine,
        medication_date: vaccinateddate,
        dosage: dosage,
        disease: medicationR,
        withdrawal: withdrawal == "Yes" ? true : false,
        withdrawal_date: withdrawal_date != "" ? withdrawal_date : null
      }
    ).then(response => {
      if (response.status === 201) {
        dispatch(getMedical(data.tag_number))
        setLoading(false)
        alert.success("Medication Added Successfully")
        closeModal(); // Added close modal for better UX
      } else {
        alert.error("Internal Server Error")
        setLoading(false)
      }
    })
      .catch(err => {
        console.log(err)
        alert.error("Internal Server Error")
        setLoading(false)
      });
  }

  // Header Component
  const HeaderBar = () => (
    <div className="bg-white border-b border-gray-200 px-6 py-4 sticky top-0 z-30 shadow-sm">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <button
            onClick={() => navigate(-1)}
            className="p-2 rounded-full bg-green-50 hover:bg-green-100 transition-colors"
          >
            <BackIcon />
          </button>
          <h1 className="text-xl font-bold text-gray-900">Medical History</h1>
        </div>

        <button
          onClick={openModal}
          className="flex items-center bg-[#009A48] hover:bg-[#007f3b] text-white px-4 py-2 rounded-lg font-bold text-sm shadow-sm transition-colors"
        >
          <PlusIcon /> Med
        </button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <HeaderBar />

      <div className="flex-1 max-w-7xl mx-auto w-full p-6 pb-24">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {data && data.length > 0 ? (
            data.map((item) => (
              <div key={item.id} className="bg-white rounded-2xl p-6 shadow-sm hover:shadow-md transition-all relative">
                {/* Card Header */}
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <p className="text-[#009A48] text-xs font-bold uppercase tracking-wider mb-1">PROBLEM</p>
                    <h3 className="text-lg font-bold text-gray-900 leading-tight">
                      {item.disease || "Unknown Issue"}
                    </h3>
                  </div>
                  <div className="bg-gray-50 p-2 rounded-full">
                    <MedicalIcon />
                  </div>
                </div>

                {/* Solution */}
                <div className="mb-4">
                  <p className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-1">SOLUTION</p>
                  <p className="text-gray-900 font-semibold">
                    {item.medication_name || "N/A"}
                  </p>
                </div>

                {/* Dosage & Date */}
                <div className="flex justify-between items-end mt-4 pt-4 border-t border-gray-50">
                  <div>
                    <p className="text-[#009A48] text-xs font-bold uppercase tracking-wider mb-1">DOSAGE</p>
                    <p className="text-[#009A48] font-bold text-lg">
                      {item.dosage || "-"}
                    </p>
                  </div>
                  <p className="text-gray-400 text-sm font-medium">
                    {item.medication_date}
                  </p>
                </div>

                {/* Withdrawal Info if present */}
                {item.withdrawal && (
                  <div className="mt-4 bg-red-50 p-3 rounded-lg">
                    <p className="text-red-800 text-xs font-bold">
                      Withdrawal Date: {item.withdrawal_date}
                    </p>
                  </div>
                )}
              </div>
            ))
          ) : (
            <div className="col-span-full flex flex-col items-center justify-center h-64 text-gray-400">
              <p>No medical history found.</p>
            </div>
          )}
        </div>
      </div>

      {/* Modal - Preserved Logic and Content */}
      <Modal
        isOpen={modalIsOpen}
        onAfterOpen={afterOpenModal}
        onRequestClose={closeModal}
        ariaHideApp={false} // React-modal requirement, or setAppElement elsewhere
        style={{
          overlay: {
            position: 'fixed',
            inset: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 50,
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center'
          },
          content: {
            position: 'relative',
            inset: 'auto',
            width: mobile ? (matches ? '400px' : '400px') : '90%',
            maxWidth: '500px',
            maxHeight: '90vh',
            padding: 0,
            border: 'none',
            background: 'transparent',
            borderRadius: SIZES.radius,
            outline: 'none',
          }
        }}
      >
        <div className="bg-white rounded-2xl overflow-hidden shadow-xl max-h-[90vh] overflow-y-auto">
          {/* Modal Header */}
          <div className="bg-[#009A48] px-6 py-4 flex items-center justify-between">
            <div
              onClick={closeModal}
              className="bg-white/20 p-2 rounded-full cursor-pointer hover:bg-white/30 transition-colors"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
              </svg>
            </div>
            <h2 className="text-white font-bold text-lg">Add Medication</h2>
            <div className="w-9"></div> {/* Spacer for centering */}
          </div>

          {/* Modal Content */}
          <div className="p-6 space-y-4">
            <InputForm
              prependComponent={<img src={IMAGES.disease} className="w-6 h-6 m-2 opacity-60" />}
              type={"text"}
              value={medicationR}
              label={"Reason for Medication"}
              onChange={(event) => setmedicationR(event.target.value)}
            />
            <InputForm
              prependComponent={<img src={IMAGES.medicines} className="w-6 h-6 m-2 opacity-60" />}
              type={"text"}
              value={medicine}
              label={"Medicine"}
              onChange={(event) => setmedicine(event.target.value)}
            />
            <InputForm
              prependComponent={<img src={IMAGES.calender} className="w-6 h-6 m-2 opacity-60" />}
              type={"date"}
              value={vaccinateddate}
              label={"Medication Date"}
              onChange={(event) => setVaccinateddate(moment(event.target.value).format("YYYY-MM-DD"))}
            />
            <InputForm
              prependComponent={<img src={IMAGES.dropper} className="w-6 h-6 m-2 opacity-60" />}
              type={"text"}
              value={dosage}
              label={"Dosage"}
              onChange={(event) => setdosage(event.target.value)}
            />

            <div className="flex flex-col space-y-2 mt-2">
              <DropDown
                value={withdrawal}
                onPress={(x) => setwithdrawal(x.value)}
                label={"Withdrawal"}
                options={checking}
              />
              {withdrawal == "Yes" && (
                <InputForm
                  prependComponent={<img src={IMAGES.calender} className="w-6 h-6 m-2 opacity-60" />}
                  type={"date"}
                  value={withdrawal_date}
                  label={"Withdrawal Date"}
                  onChange={(event) => setwithdrawal_date(event.target.value)}
                />
              )}
            </div>

            <div className="mt-6">
              {loading ? <Loading /> : (
                <TextButton
                  label={"Add Medication"}
                  icon={IMAGES.med}
                  onPress={() => addmedical()}
                  buttonContainerStyle={{ backgroundColor: '#009A48', marginTop: 10 }}
                />
              )}
            </div>
          </div>
        </div>
      </Modal>
    </div>
  )
}
